import re
import xml.etree.ElementTree as ET

text = open("/private/tmp/claude-501/-Users-josemejia-Documents-Software-Development-Qualitara-relay-activity-health/485c1256-5727-457d-8aec-65bc845ee171/scratchpad/plan.out").read()
ns = {"p": "http://schemas.microsoft.com/sqlserver/2004/07/showplan"}
for xml in re.findall(r"<ShowPlanXML.*?</ShowPlanXML>", text, re.S):
    root = ET.fromstring(xml)
    stmt = root.find(".//p:StmtSimple", ns)
    if stmt is None or "OPENJSON" not in (stmt.get("StatementText") or ""):
        continue
    print("=== statement, rows est", stmt.get("StatementEstRows"))
    qt = root.find(".//p:QueryTimeStats", ns)
    if qt is not None:
        print("QueryTimeStats cpu", qt.get("CpuTime"), "ms elapsed", qt.get("ElapsedTime"), "ms")

    def walk(node, depth):
        for relop in node.findall("p:RelOp", ns) if depth else [node]:
            rt = relop.find("p:RunTimeInformation/p:RunTimeCountersPerThread", ns)
            rows = rt.get("ActualRows") if rt is not None else "?"
            execs = rt.get("ActualExecutions") if rt is not None else "?"
            extra = ""
            obj = relop.find(".//p:IndexScan/p:Object", ns)
            if relop.get("PhysicalOp") in ("Index Seek", "Index Scan", "Clustered Index Scan", "Clustered Index Seek") and obj is not None:
                extra = f" [{obj.get('Index')}]"
                seek = relop.find(".//p:SeekPredicates", ns)
                if seek is not None:
                    cols = [c.get("Column") for c in seek.findall(".//p:ColumnReference", ns) if c.get("Column") in ("account_id", "occurred_at")]
                    extra += f" seek keys on {sorted(set(cols))}"
                if relop.find(".//p:IndexScan/p:Predicate", ns) is not None:
                    extra += " + residual predicate"
            print("  " * depth + f"{relop.get('PhysicalOp')} / {relop.get('LogicalOp')}  actualRows={rows} executions={execs}{extra}")
            for child in relop.iter():
                pass
            for child_container in relop:
                for sub in child_container.iter():
                    if sub.tag.endswith("RelOp") and sub is not relop:
                        pass
            children = []
            for sub in relop:
                children.extend(sub.findall("p:RelOp", ns))
            for child in children:
                walk_one(child, depth + 1)

    def walk_one(relop, depth):
        rt = relop.find("p:RunTimeInformation/p:RunTimeCountersPerThread", ns)
        rows = rt.get("ActualRows") if rt is not None else "?"
        execs = rt.get("ActualExecutions") if rt is not None else "?"
        extra = ""
        obj = relop.find("./*/p:Object", ns)
        if obj is not None and obj.get("Index"):
            extra = f" [{obj.get('Index')}]"
            seek = relop.find("./*/p:SeekPredicates", ns)
            if seek is not None:
                cols = [c.get("Column") for c in seek.findall(".//p:ColumnReference", ns) if c.get("Column") in ("account_id", "occurred_at")]
                extra += f" seek keys on {sorted(set(cols))}"
            if relop.find("./*/p:Predicate", ns) is not None:
                extra += " + residual predicate"
        print("  " * depth + f"{relop.get('PhysicalOp')} / {relop.get('LogicalOp')}  actualRows={rows} executions={execs}{extra}")
        for sub in relop:
            for child in sub.findall("p:RelOp", ns):
                walk_one(child, depth + 1)
            for grand in sub:
                for child in grand.findall("p:RelOp", ns):
                    walk_one(child, depth + 1)

    walk_one(root.find(".//p:QueryPlan/p:RelOp", ns), 0)

